@import url('https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323:wght@400&display=swap');

:root {
  --bg: #0d0021;
  --ink: #ff6ec7;
  --mid: #ffe04b;
  --border: #7b2fff;
  --accent: #00f0ff;
  --font: 'Press Start 2P', monospace;
  --pad-x: 24px;
  --pad-top: 32px;
}

/* Pixel star background */
.page {
  background-color: #0d0021;
  background-image:
    radial-gradient(circle, #fff 1px, transparent 1px),
    radial-gradient(circle, #ffe04b 1px, transparent 1px),
    radial-gradient(circle, #ff6ec7 1px, transparent 1px);
  background-size: 120px 120px, 200px 200px, 170px 170px;
  background-position: 0 0, 60px 40px, 30px 80px;
  animation: starScroll 12s linear infinite;
  font-family: var(--font);
  min-height: 100vh;
  overflow-x: hidden;
}

@keyframes starScroll {
  from { background-position: 0 0, 60px 40px, 30px 80px; }
  to   { background-position: 120px 0, 180px 40px, 150px 80px; }
}

/* Rainbow trail bar at top */
.page::before {
  content: '';
  display: block;
  position: fixed;
  top: 0; left: 0; right: 0;
  height: 8px;
  background: linear-gradient(90deg,
    #ff0000, #ff7700, #ffff00, #00ff00, #0099ff, #cc00ff, #ff0000);
  background-size: 200% 100%;
  animation: rainbowScroll 1.5s linear infinite;
  z-index: 9999;
  image-rendering: pixelated;
}

.page::after {
  content: '🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩🍩';
  position: fixed;
  bottom: 8px;
  left: 0;
  white-space: nowrap;
  font-size: 28px;
  animation: donutMarch 8s linear infinite;
  z-index: 9998;
  opacity: 0.85;
  pointer-events: none;
}

@keyframes rainbowScroll {
  from { background-position: 0% 0%; }
  to   { background-position: 200% 0%; }
}

@keyframes donutMarch {
  from { transform: translateX(100vw); }
  to   { transform: translateX(-120%); }
}

/* Intro layout */
.intro {
  border: 4px solid var(--border);
  box-shadow: 6px 6px 0 #ff6ec7, 12px 12px 0 #ffe04b;
  margin: 32px 16px;
  background: rgba(123, 47, 255, 0.15);
  image-rendering: pixelated;
  position: relative;
}

.intro::before {
  content: '🌈 NYAN ZONE 🌈';
  position: absolute;
  top: -18px;
  left: 16px;
  background: #0d0021;
  color: #ffe04b;
  font-size: 10px;
  padding: 2px 8px;
  font-family: 'Press Start 2P', monospace;
  letter-spacing: 2px;
}

.intro-headline {
  font-size: clamp(14px, 3vw, 22px);
  color: #ff6ec7;
  text-shadow:
    2px 2px 0 #7b2fff,
    4px 4px 0 #0d0021;
  line-height: 1.8;
  letter-spacing: 1px;
  animation: colorPulse 2s ease-in-out infinite alternate;
}

@keyframes colorPulse {
  from { color: #ff6ec7; text-shadow: 2px 2px 0 #7b2fff, 4px 4px 0 #0d0021; }
  to   { color: #00f0ff; text-shadow: 2px 2px 0 #ff6ec7, 4px 4px 0 #0d0021; }
}

.bio-text {
  color: #ffe04b;
  font-family: 'VT323', monospace;
  font-size: 20px;
  line-height: 1.6;
  border-left: 4px solid #7b2fff;
  padding-left: 12px;
  margin-top: 12px;
}

.contact-line {
  color: #00f0ff;
  margin-top: 16px;
  letter-spacing: 2px;
}

.contact-line a,
.contact-trigger {
  color: #ffe04b !important;
  text-decoration: none;
  border-bottom: 2px dashed #ff6ec7;
  transition: color 0.2s, box-shadow 0.2s;
}

.contact-line a:hover,
.contact-trigger:hover {
  color: #ff6ec7 !important;
  text-shadow: 0 0 8px #ff6ec7, 0 0 16px #7b2fff;
}

/* Section label */
.section-label {
  color: #ffe04b;
  font-size: 9px;
  letter-spacing: 4px;
  text-transform: uppercase;
  border-bottom: 3px solid #7b2fff;
  padding-bottom: 8px;
  position: relative;
}

.section-label::before {
  content: '🍩 ';
}

.section-label::after {
  content: ' 🍩';
}

/* Work items */
.work-section {
  margin: 24px 16px;
}

.work-item {
  border: 3px solid #7b2fff;
  box-shadow: 4px 4px 0 #ff6ec7;
  background: rgba(13, 0, 33, 0.8);
  margin-bottom: 28px;
  transition: transform 0.15s, box-shadow 0.15s;
  position: relative;
  overflow: hidden;
}

.work-item::before {
  content: '';
  display: block;
  height: 6px;
  background: linear-gradient(90deg,
    #ff0000, #ff7700, #ffff00, #00ff00, #0099ff, #cc00ff);
  background-size: 200% 100%;
  animation: rainbowScroll 1s linear infinite;
}

.work-item:hover {
  transform: translate(-4px, -4px);
  box-shadow: 8px 8px 0 #ffe04b, 12px 12px 0 #7b2fff;
}

.work-image {
  border-bottom: 3px solid #7b2fff;
  image-rendering: pixelated;
}

.work-title {
  color: #ff6ec7;
  font-size: 11px;
  text-shadow: 2px 2px 0 #7b2fff;
  font-family: 'Press Start 2P', monospace;
  margin-bottom: 8px;
}

.work-desc {
  color: #ffe04b;
  font-family: 'VT323', monospace;
  font-size: 18px;
  line-height: 1.5;
}

.work-tags {
  margin-top: 8px;
}

.tag {
  background: #7b2fff;
  color: #ffe04b;
  font-size: 7px;
  font-family: 'Press Start 2P', monospace;
  border: 2px solid #ff6ec7;
  padding: 3px 6px;
  margin: 2px;
  display: inline-block;
  image-rendering: pixelated;
  transition: background 0.15s, color 0.15s;
}

.tag:hover {
  background: #ff6ec7;
  color: #0d0021;
}

/* Work item footer */
.work-item-footer {
  padding: 8px 12px;
  border-top: 2px dashed #7b2fff;
}

/* Footer */
footer {
  border-top: 4px solid #7b2fff;
  background: rgba(123, 47, 255, 0.2);
  color: #ffe04b;
  font-size: 8px;
  padding: 24px;
  text-align: center;
  letter-spacing: 2px;
  position: relative;
}

footer::before {
  content: '🍩 ★ 🌈 ★ 🍩 ★ 🌈 ★ 🍩 ★ 🌈 ★ 🍩';
  display: block;
  font-size: 16px;
  margin-bottom: 12px;
  animation: donutSpin 4s linear infinite;
}

@keyframes donutSpin {
  0%   { letter-spacing: 2px; color: #ff6ec7; }
  25%  { letter-spacing: 6px; color: #ffe04b; }
  50%  { letter-spacing: 2px; color: #00f0ff; }
  75%  { letter-spacing: 6px; color: #7b2fff; }
  100% { letter-spacing: 2px; color: #ff6ec7; }
}

.footer-nav a {
  color: #00f0ff !important;
  font-size: 7px;
  margin: 0 8px;
  text-decoration: none;
  border-bottom: 2px dashed #ff6ec7;
  transition: color 0.2s;
}

.footer-nav a:hover {
  color: #ff6ec7 !important;
}

/* Case study */
.top-nav {
  background: rgba(13, 0, 33, 0.9);
  border-bottom: 3px solid #7b2fff;
  padding: 12px 24px;
}

.back-link {
  color: #00f0ff !important;
  font-size: 8px;
  text-decoration: none;
  font-family: 'Press Start 2P', monospace;
}

.back-link::before {
  content: '🍩 ◀ ';
}

.cs-title {
  color: #ff6ec7;
  font-size: clamp(14px, 3vw, 24px);
  text-shadow: 3px 3px 0 #7b2fff;
  font-family: 'Press Start 2P', monospace;
  line-height: 1.7;
}

.cs-section-label {
  color: #ffe04b;
  font-size: 9px;
  letter-spacing: 3px;
  border-left: 5px solid #ff6ec7;
  padding-left: 10px;
  font-family: 'Press Start 2P', monospace;
}

.callout {
  background: rgba(123, 47, 255, 0.25);
  border-left: 6px solid #ff6ec7;
  border-right: 6px solid #00f0ff;
  color: #ffe04b;
  font-family: 'VT323', monospace;
  font-size: 20px;
  padding: 16px 20px;
  box-shadow: 4px 0 #7b2fff;
}

.meta-label {
  color: #7b2fff;
  font-size: 7px;
  font-family: 'Press Start 2P', monospace;
  letter-spacing: 2px;
}

.meta-value {
  color: #00f0ff;
  font-family: 'VT323', monospace;
  font-size: 20px;
}

/* Popup */
.popup-overlay {
  background: rgba(13, 0, 33, 0.92);
}

.popup-card {
  background: #0d0021;
  border: 4px solid #7b2fff;
  box-shadow: 8px 8px 0 #ff6ec7, 16px 16px 0 #ffe04b;
  font-family: 'Press Start 2P', monospace;
}

.popup-title {
  color: #ff6ec7;
  font-size: 14px;
  text-shadow: 2px 2px 0 #7b2fff;
}

.popup-title::before {
  content: '🍩 ';
}

.popup-title::after {
  content: ' 🍩';
}

.popup-sub {
  color: #ffe04b;
  font-family: 'VT323', monospace;
  font-size: 18px;
}

.popup-form input,
.popup-form textarea {
  background: #1a003a;
  border: 2px solid #7b2fff;
  color: #00f0ff;
  font-family: 'VT323', monospace;
  font-size: 16px;
  padding: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.popup-form input:focus,
.popup-form textarea:focus {
  border-color: #ff6ec7;
  box-shadow: 0 0 10px #ff6ec7;
}

.btn-submit {
  background: #7b2fff;
  color: #ffe04b;
  border: 3px solid #ff6ec7;
  font-family: 'Press Start 2P', monospace;
  font-size: 9px;
  padding: 10px 20px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  box-shadow: 3px 3px 0 #ff6ec7;
}

.btn-submit:hover {
  background: #ff6ec7;
  color: #0d0021;
  transform: translate(-2px, -2px);
  box-shadow: 5px 5px 0 #ffe04b;
}

.btn-close {
  background: transparent;
  color: #ff6ec7;
  border: 2px dashed #7b2fff;
  font-family: 'Press Start 2P', monospace;
  font-size: 7px;
  cursor: pointer;
  padding: 6px 12px;
}

.btn-close:hover {
  color: #ffe04b;
  border-color: #ffe04b;
}

/* Scrollbar */
::-webkit-scrollbar { width: 10px; background: #0d0021; }
::-webkit-scrollbar-track { background: #0d0021; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #ff6ec7, #7b2fff, #00f0ff);
  border: 2px solid #0d0021;
}

